1. import { getDefaultProvider, providers, Wallet } from 'ethers';
2. import { ArgumentsCamelCase, InferredOptionTypes, Options } from 'yargs';
3. import { assetChains, Assets, ChainflipNetworks } from '@/shared/enums';
4. import { assert } from '@/shared/guards';
5. import {
6.   executeSwap,
7.   type SwapNetworkOptions,
8.   type ExecuteSwapParams,
9. } from '@/shared/vault';
10. import { askForPrivateKey, getEthNetwork, cliNetworks } from '../utils';
11. 
12. export const yargsOptions = {
13.   'src-asset': {
14.     choices: Object.values(Assets),
15.     demandOption: true,
16.     describe: 'The asset to swap from',
17.   },
18.   'dest-asset': {
19.     choices: Object.values(Assets),
20.     demandOption: true,
21.     describe: 'The asset to swap to',
22.   },
23.   'chainflip-network': {
24.     choices: cliNetworks,
25.     describe: 'The Chainflip network to execute the swap on',
26.     default: ChainflipNetworks.sisyphos,
27.   },
28.   amount: {
29.     type: 'string',
30.     demandOption: true,
31.     describe: 'The amount to swap',
32.   },
33.   'dest-address': {
34.     type: 'string',
35.     demandOption: true,
36.     describe: 'The address to send the swapped assets to',
37.   },
38.   message: {
39.     type: 'string',
40.     describe: 'The message that is sent along with the swapped assets',
41.   },
42.   'gas-budget': {
43.     type: 'string',
44.     describe: 'The amount of gas that is sent with the message',
45.   },
46.   'wallet-private-key': {
47.     type: 'string',
48.     describe: 'The private key of the wallet to use',
49.   },
50.   'src-token-contract-address': {
51.     type: 'string',
52.     describe:
53.       'The contract address of the token to swap from when `chainflip-network` is `localnet`',
54.   },
55.   'vault-contract-address': {
56.     type: 'string',
57.     describe:
58.       'The contract address of the vault when `chainflip-network` is `localnet`',
59.   },
60.   'eth-network': {
61.     type: 'string',
62.     describe:
63.       'The eth network URL to use when `chainflip-network` is `localnet`',
64.   },
65. } as const satisfies { [key: string]: Options };
66. 
67. export default async function cliExecuteSwap(
68.   args: ArgumentsCamelCase<InferredOptionTypes<typeof yargsOptions>>,
69. ) {
70.   const privateKey = args.walletPrivateKey ?? (await askForPrivateKey());
71. 
72.   const ethNetwork = getEthNetwork(args);
73. 
74.   const wallet = new Wallet(privateKey).connect(
75.     process.env.ALCHEMY_KEY
76.       ? new providers.AlchemyProvider(ethNetwork, process.env.ALCHEMY_KEY)
77.       : getDefaultProvider(ethNetwork),
78.   );
79. 
80.   const networkOpts: SwapNetworkOptions =
81.     args.chainflipNetwork === 'localnet'
82.       ? {
83.           vaultContractAddress: args.vaultContractAddress as string,
84.           srcTokenContractAddress: args.srcTokenContractAddress as string,
85.           signer: wallet,
86.           network: args.chainflipNetwork,
87.         }
88.       : { network: args.chainflipNetwork, signer: wallet };
89. 
90.   let ccmMetadata;
91.   if (args.gasBudget || args.message) {
92.     assert(args.gasBudget, 'missing gas budget');
93.     assert(args.message, 'missing message');
94.     ccmMetadata = {
95.       message: args.message,
96.       gasBudget: args.gasBudget,
97.     };
98.   }
99. 
100.   const receipt = await executeSwap(
101.     {
102.       srcChain: assetChains[args.srcAsset],
103.       srcAsset: args.srcAsset,
104.       destChain: assetChains[args.destAsset],
105.       destAsset: args.destAsset,
106.       amount: args.amount,
107.       destAddress: args.destAddress,
108.       ccmMetadata,
109.     } as ExecuteSwapParams,
110.     networkOpts,
111.     {},
112.   );
113. 
114.   console.log(`Swap executed. Transaction hash: ${receipt.transactionHash}`);
115. }
116.

