1. import axios from 'axios';
2. import { ethers } from 'ethers';
3. import { z } from 'zod';
4. import { assetDecimals } from '@/shared/enums';
5. import logger from '../utils/logger';
6. 
7. let lastJsonRpcRequestId = 0;
8. 
9. const depositTrackerResponseSchema = z.object({
10.   id: z.number(),
11.   jsonrpc: z.string(),
12.   result: z.array(
13.     z
14.       .object({
15.         confirmations: z.number(),
16.         value: z.number(),
17.         tx_hash: z.string(),
18.       })
19.       .nullable(),
20.   ),
21. });
22. 
23. export const fetchPendingBitcoinDeposit = async (address: string) => {
24.   if (!process.env.BITCOIN_DEPOSIT_TRACKER_URL) {
25.     logger.error(
26.       'cannot fetch pending deposit because BITCOIN_DEPOSIT_TRACKER_URL is not set',
27.     );
28.     return undefined;
29.   }
30. 
31.   try {
32.     const response = await axios.post(
33.       process.env.BITCOIN_DEPOSIT_TRACKER_URL,
34.       {
35.         id: ++lastJsonRpcRequestId, // eslint-disable-line no-plusplus
36.         jsonrpc: '2.0',
37.         method: 'status',
38.         params: [address],
39.       },
40.       {
41.         headers: {
42.           'Content-Type': 'application/json',
43.         },
44.         timeout: 500,
45.       },
46.     );
47.     const data = depositTrackerResponseSchema.safeParse(response.data);
48. 
49.     if (data.success && data.data.result[0]) {
50.       return {
51.         amount: ethers.utils
52.           .parseUnits(String(data.data.result[0].value), assetDecimals.BTC)
53.           .toString(),
54.         transactionConfirmations: data.data.result[0].confirmations,
55.         transactionHash: `0x${data.data.result[0].tx_hash}`,
56.       };
57.     }
58. 
59.     if (!data.success) {
60.       logger.error(
61.         'unexpected response from bitcoin deposit tracker',
62.         response.data,
63.       );
64.     }
65.   } catch (error) {
66.     logger.error('failed to fetch status from bitcoin deposit tracker', {
67.       error,
68.     });
69.   }
70. 
71.   return undefined;
72. };
