54. export const checkAllowance = async (
55.   amount: BigNumberish,
56.   spenderAddress: string,
57.   erc20Address: string,
58.   signer: Signer,
59. ) => {
60.   const erc20 = ERC20__factory.connect(erc20Address, signer);
61.   const signerAddress = await signer.getAddress();
62.   const allowance = await erc20.allowance(signerAddress, spenderAddress);
63.   return { allowance, isAllowable: allowance.gte(amount), erc20 };
64. };
