   type BigNumberish,
 } from 'ethers';

 type BigNumberJson = {
   type: 'BigNumber';
   hex: string;
 };

 const bigNumberValues = new WeakMap<BigNumber, bigint>();

 export class BigNumber {
   private constructor(value: BigNumberish) {
     bigNumberValues.set(this, getBigInt(value));
   }

   static from(value: BigNumberish): BigNumber {
     return new BigNumber(value);
   }

   gte(value: BigNumberish | BigNumber): boolean {
     return this.toBigInt() >= toBigInt(value);
   }

   sub(value: BigNumberish | BigNumber): BigNumber {
     return BigNumber.from(this.toBigInt() - toBigInt(value));
   }

   toBigInt(): bigint {
     const value = bigNumberValues.get(this);
     if (value === undefined) {
       throw new Error('Invalid BigNumber instance');
     }
     return value;
   }

   toHexString(): string {
     return toBeHex(this.toBigInt());
   }

   toString(): string {
     return this.toBigInt().toString();
   }

   toJSON(): BigNumberJson {
     return { type: 'BigNumber', hex: this.toHexString() };
   }
 }

 export const isBigNumber = (value: unknown): value is BigNumber =>
   value instanceof BigNumber;

 export const toBigInt = (value: BigNumberish | BigNumber): bigint =>
   isBigNumber(value) ? value.toBigInt() : getBigInt(value);

 export const toBigNumber = (value: BigNumberish | BigNumber): BigNumber =>
